function cinemaWait(ms,next){clearTimeout(cinemaTimer);cinemaRemaining=ms;cinemaNext=next;if(document.hidden)return;cinemaDue=performance.now()+ms;cinemaTimer=setTimeout(()=>{cinemaTimer=null;cinemaNext=null;next()},ms)}
