// The approved preview clock: black 0–5s; flash 35.3s; APC 36.75s.
function startTitleGlow(reduced){const screen=document.querySelector('.cinematic-title'),svg=screen?.querySelector('svg'),glow=screen?.querySelector('.title-glow'),flash=document.querySelector('.title-flash');if(!svg||!glow)return;const box=svg.getBoundingClientRect(),origin={x:box.x+box.width*570/1260,y:box.y+box.height*95/190};glow.style.left=origin.x+'px';glow.style.top=origin.y+'px';flash?.style.setProperty('--flash-x',origin.x+'px');flash?.style.setProperty('--flash-y',origin.y+'px');if(reduced){glow.remove();return}const scale=innerWidth/960;glow.style.width=1695*scale+'px';glow.style.height=1695*.72*scale+'px';const frames=[];for(let i=0;i<=606;i++){const time=i/20,progress=Math.max(0,Math.min(1,(time-1)/29.3)),size=45+Math.pow(progress,2.6)*1650;frames.push({offset:i/606,opacity:time<1?0:.03+Math.pow(progress,3.2)*.95,transform:`translate(-50%,-50%) scale(${size/1695})`})}ui.titleGlowAnimation=glow.animate(frames,{duration:30300,fill:'forwards'});if(document.hidden)ui.titleGlowAnimation.pause()}
