function currentBpm(){if(!s||s.phase!=='play'||ui.boot!=='game')return 0;let p=me(),d=dist(p.pos,s.alien);return p.captive||d<=1?132:d===2?104:d===3?78:62}
function trackerContact(){if(!s||ui.boot!=='game'||s.phase!=='play'||ui.private||ui.popup||ui.sequence||s.pendingEvent)return null;const p=me(),d=dist(p.pos,s.alien);if(d>2)return null;const a=MAP[s.alien],c=MAP[p.pos];return {distance:d,x:70+((a.q-c.q)+(a.r-c.r)/2)*16,y:46+(a.r-c.r)*13.856}}
