// Remember physical contact independently of modal visibility and sound toggles.
const trackerContacts=new WeakMap();
function updateTrackerSting(){if(!s)return;for(const p of s.players){const inRange=!p.captive&&dist(p.pos,s.alien)<=2;let contact=trackerContacts.get(p);if(!inRange){trackerContacts.delete(p);continue}if(!contact){contact={fired:false};trackerContacts.set(p,contact)}if(p===me()&&!contact.fired&&trackerContact()&&!document.hidden){contact.fired=true;if(soundOn)ShipAudio.play('trackerSting')}}}
function scheduleTracker(){updateTrackerSting();const delay=trackerInterval();if(trackerTimer&&lastTrackerDelay===delay)return;clearTimeout(trackerTimer);trackerTimer=null;lastTrackerDelay=delay;if(!delay){ShipAudio.stopEffect('tracker');return}const ping=()=>{trackerTimer=null;const next=trackerInterval();if(!next){lastTrackerDelay=0;ShipAudio.stopEffect('tracker');return}trackerBeatAt=Date.now();ShipAudio.play('tracker');lastTrackerDelay=next;trackerTimer=setTimeout(ping,next)};ping()}
function trackerMarkup(){const contact=trackerContact(),period=contact?.distance<=1?650:1100;return `<aside class="motion-tracker ${contact?'contact':''}" aria-label="Motion tracker: ${contact?'alien detected within two hexes':'no contact within two hexes'}"><div class="tracker-label">MOTION TRACKER</div><div class="tracker-display"><svg viewBox="0 0 140 92" aria-hidden="true"><path class="tracker-grid" d="M14 23H126M14 46H126M14 69H126M42 9V83M70 9V83M98 9V83"/><circle class="tracker-ring" cx="70" cy="46" r="34"/><circle class="tracker-ring" cx="70" cy="46" r="17"/><path class="tracker-sweep" d="M70 46L103 38"/><path class="tracker-origin" d="M66 46H74M70 42V50"/>${contact?`<circle class="tracker-blip" cx="${contact.x.toFixed(2)}" cy="${contact.y.toFixed(2)}" r="3.8" style="--ping-period:${period}ms;--ping-offset:-${(Date.now()-trackerBeatAt)%period}ms"/>`:''}</svg><div class="tracker-readout">${contact?'CONTACT':'NO CONTACT'}</div></div><div class="tracker-range">RANGE · 02 HEX</div></aside>`}
