// MU-TH-UR terminal: one visual/audio clock, preserved across incidental renders.
const terminalSessions=new Map();let terminalRun=null;
function stopTerminal(){if(terminalRun){clearTimeout(terminalRun.timer);terminalRun=null}}
function terminalMarkup(key,content){return `<div class="muthur-copy" data-terminal="${key}" role="group" aria-label="MU-TH-UR transmission">${content}<span class="terminal-cursor typing-cursor" aria-hidden="true">█</span></div>`}
function mountTerminal(restart=false,onDone=null){
 const region=document.querySelector('[data-terminal]');if(!region){stopTerminal();return}
 if(terminalRun?.region===region&&!restart)return;
 stopTerminal();const key=region.dataset.terminal;
 const nodes=[...region.querySelectorAll('[data-terminal-line]')];
 const lines=nodes.map(node=>node.getAttribute('aria-label')||node.textContent),signature=lines.join('\n');
 let session=terminalSessions.get(key);
 if(restart||!session||session.signature!==signature){session={signature,count:0,done:false};terminalSessions.set(key,session);if(terminalSessions.size>16)terminalSessions.delete(terminalSessions.keys().next().value)}
 const total=lines.reduce((n,line)=>n+line.length,0),cursor=region.querySelector('.typing-cursor');
 const spans=nodes.map((node,i)=>{node.setAttribute('aria-label',lines[i]);node.classList.add('terminal-line');node.textContent='';let ghost=document.createElement('span'),visible=document.createElement('span');ghost.className='terminal-ghost';ghost.setAttribute('aria-hidden','true');ghost.textContent=(node.dataset.prefix||'')+lines[i];visible.className='terminal-visible';visible.setAttribute('aria-hidden','true');node.append(ghost,visible);return visible});
 const run={region,session,lines,spans,total,cursor,onDone,timer:null,key};terminalRun=run;
 function paint(){let remaining=session.count,active=spans[0];for(let i=0;i<spans.length;i++){let n=Math.min(lines[i].length,Math.max(0,remaining));const prefix=nodes[i].dataset.prefix||'';nodes[i].style.visibility=prefix&&remaining<0?'hidden':'';spans[i].textContent=(remaining>=0||session.done?prefix:'')+lines[i].slice(0,n);if(remaining>=0&&remaining<=lines[i].length)active=spans[i];remaining-=lines[i].length}active?.append(cursor);region.dataset.typing=session.done?'done':'active'}
 run.paint=paint;paint();
 run.finish=()=>{if(terminalRun!==run)return;clearTimeout(run.timer);session.count=total;session.done=true;paint();const done=run.onDone;run.onDone=null;done?.()};
 if(session.done){run.onDone?.();return}
 if(matchMedia('(prefers-reduced-motion: reduce)').matches){run.finish();return}
 function tick(){if(terminalRun!==run||!region.isConnected||document.hidden)return;session.count++;paint();let offset=session.count,ch='',boundary=false;for(const line of lines){if(offset<=line.length){ch=line[offset-1]||'';boundary=offset===line.length;break}offset-=line.length}if(session.count>=total){run.finish();return}let delay=key==='boot'?80:12;if(boundary){delay=key==='boot'?1200:90}run.timer=setTimeout(tick,delay)}
 run.timer=setTimeout(tick,key==='boot'?200:100);

}
function revealTerminal(){if(!terminalRun||terminalRun.session.done)return false;terminalRun.finish();return true}
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopTerminal();clearTimeout(trackerTimer);trackerTimer=null;clearTimeout(alienTimer);alienTimer=null}else{mountTerminal(false,ui.introActivated&&ui.boot==='boot'?finishIntro:null);scheduleTracker();scheduleAlienAmbience()}});
